// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, IERC20, ICVXBooster} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;
    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(new __InvMutHandleStub())), ICVXBooster(address(new __InvMutHandleStub())), new address[](0)); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != newOwner);
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        vm.prank(caller);
        address observed = c.owner();
        assertTrue(observed == newOwner);
    }
}
